        if(mapped[i]!=exp){ if(fails<5) printf("  [%u] got %u exp %u\n",i,mapped[i],exp); fails++; }
    }
    vkUnmapMemory(device,mem);
    printf("  %s: %s (%d/%d wrong)\n", useSubgroup?"subgroupBroadcast":"no-subgroup", fails==0?"PASS":"FAIL", fails, N);
    // cleanup
    vkDestroyPipeline(device,pipe,nullptr); vkDestroyShaderModule(device,sm,nullptr); vkDestroyPipelineLayout(device,pll,nullptr); vkDestroyDescriptorSetLayout(device,dsl,nullptr); vkDestroyDescriptorPool(device,dp,nullptr); vkDestroyCommandPool(device,cpool,nullptr); vkDestroyBuffer(device,buf,nullptr); vkFreeMemory(device,mem,nullptr);
    return fails==0?0:1;
}

