// Minimal Vulkan compute probe to localize the Intel Arc correctness failure.
// Runs 3 compute shaders (no-subgroup / subgroupBroadcast / subgroupAdd) on the
// Intel device and reports PASS/FAIL for each. Readback via host-coherent buffer.
#define VK_NO_PROTOTYPES
#include "volk.h"

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <string>

