static std::vector<uint32_t> loadSpv(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) { printf("  cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    std::vector<uint32_t> code(n / 4);
    if (fread(code.data(), 1, n, f) != (size_t)n) { printf("  short read %s\n", path); exit(1); }
    fclose(f);
    return code;
}

// kind: 0=no-subgroup, 1=broadcast, 2=add
static int runTest(VkDevice device, VkPhysicalDevice phys, uint32_t qfam,
                   const char* spvPath, int kind, uint32_t sgSize) {
    const uint32_t N = 1024;
    const VkDeviceSize bytesz = (VkDeviceSize)N * sizeof(uint32_t);

    VkBufferCreateInfo bci{}; bci.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
    bci.size = bytesz; bci.usage = VK_BUFFER_USAGE_STORAGE_BUFFER_BIT;
