    if (memType == 0xFFFFFFFF) { printf("  no host-visible coherent mem type\n"); return -1; }
    VkMemoryAllocateInfo mai{}; mai.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
    mai.allocationSize = mr.size; mai.memoryTypeIndex = memType;
