    VkDescriptorSetAllocateInfo dsai{}; dsai.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;
    dsai.descriptorPool = dp; dsai.descriptorSetCount = 1; dsai.pSetLayouts = &dsl;
    VkDescriptorSet ds; CHECK(vkAllocateDescriptorSets(device, &dsai, &ds));
    VkDescriptorBufferInfo dbi{}; dbi.buffer = buf; dbi.offset = 0; dbi.range = bytesz;
    VkWriteDescriptorSet wds{}; wds.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
    wds.dstSet = ds; wds.dstBinding = 0; wds.descriptorCount = 1;
    wds.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; wds.pBufferInfo = &dbi;
    vkUpdateDescriptorSets(device, 1, &wds, 0, nullptr);

    VkCommandPool cpool; VkCommandPoolCreateInfo cpci{}; cpci.sType = VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO;
    cpci.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT; cpci.queueFamilyIndex = qfam;
    CHECK(vkCreateCommandPool(device, &cpci, nullptr, &cpool));
    VkCommandBuffer cb; VkCommandBufferAllocateInfo cbai{}; cbai.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO;
    cbai.commandPool = cpool; cbai.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY; cbai.commandBufferCount = 1;
    CHECK(vkAllocateCommandBuffers(device, &cbai, &cb));

    VkCommandBufferBeginInfo cbbi{}; cbbi.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
    CHECK(vkBeginCommandBuffer(cb, &cbbi));
    vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_COMPUTE, pipe);
    vkCmdBindDescriptorSets(cb, VK_PIPELINE_BIND_POINT_COMPUTE, pll, 0, 1, &ds, 0, nullptr);
    vkCmdDispatch(cb, N / 32, 1, 1);
    CHECK(vkEndCommandBuffer(cb));

    VkQueue q; vkGetDeviceQueue(device, qfam, 0, &q);
    VkSubmitInfo si{}; si.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO; si.commandBufferCount = 1; si.pCommandBuffers = &cb;
    CHECK(vkQueueSubmit(q, 1, &si, VK_NULL_HANDLE));
    CHECK(vkQueueWaitIdle(q));

    CHECK(vkMapMemory(device, mem, 0, bytesz, 0, (void**)&mapped));
    int fails = 0; uint32_t firstBadIdx = 0; uint32_t firstBadGot = 0, firstBadExp = 0;
    for (uint32_t i = 0; i < N; i++) {
        uint32_t exp;
        if (kind == 0) exp = (i + 1) * 7u + 3u;                 // simple
        else { uint32_t s = i / sgSize; exp = s * sgSize + 1u; } // broadcast (lane0 val of subgroup)
        if (kind == 2) { uint32_t s = i / sgSize; exp = sgSize * s * sgSize + (sgSize * (sgSize + 1u)) / 2u; }
