    const char* nm = (kind == 0) ? "no-subgroup(mul) " : (kind == 1) ? "subgroupBroadcast" : "subgroupAdd(reduce)";
    printf("  %-18s %s  (%d/%d wrong", nm, fails == 0 ? "PASS" : "FAIL", fails, N);
    if (fails) printf("; first idx=%u got=%u exp=%u", firstBadIdx, firstBadGot, firstBadExp);
    printf(")\n");

    vkDestroyPipeline(device, pipe, nullptr); vkDestroyShaderModule(device, sm, nullptr);
    vkDestroyPipelineLayout(device, pll, nullptr); vkDestroyDescriptorSetLayout(device, dsl, nullptr);
    vkDestroyDescriptorPool(device, dp, nullptr); vkDestroyCommandPool(device, cpool, nullptr);
    vkDestroyBuffer(device, buf, nullptr); vkFreeMemory(device, mem, nullptr);
