// Minimal Vulkan compute probe + subgroup-size-control workaround test.
// Runs compute shaders at DEFAULT reported subgroup size and at FORCED subgroup size
// to confirm/refute the "report 32, execute 16" driver mismatch and the 16-wide fix.
#define VK_NO_PROTOTYPES
#include "volk.h"

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <string>

#define CHECK(x) do { VkResult _r = (x); if (_r != VK_SUCCESS) { printf("  VULKAN ERR %s = %d (line %d)\n", #x, _r, __LINE__); return -1; } } while(0)

static std::vector<uint32_t> loadSpv(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) { printf("  cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    std::vector<uint32_t> code(n / 4);
    if (fread(code.data(), 1, n, f) != (size_t)n) { printf("  short read %s\n", path); exit(1); }
    fclose(f);
    return code;
}

// kind: 0=no-subgroup, 1=broadcast, 2=add ; reqSg: 0=default, >0 force via VK_EXT_subgroup_size_control
static int runTest(VkDevice device, VkPhysicalDevice phys, uint32_t qfam,
                   const char* spvPath, int kind, uint32_t expSg, uint32_t reqSg) {
    const uint32_t N = 1024;
    const VkDeviceSize bytesz = (VkDeviceSize)N * sizeof(uint32_t);

    VkBufferCreateInfo bci{}; bci.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
    bci.size = bytesz; bci.usage = VK_BUFFER_USAGE_STORAGE_BUFFER_BIT;
    VkBuffer buf; CHECK(vkCreateBuffer(device, &bci, nullptr, &buf));
    VkMemoryRequirements mr; vkGetBufferMemoryRequirements(device, buf, &mr);
    VkPhysicalDeviceMemoryProperties mp; vkGetPhysicalDeviceMemoryProperties(phys, &mp);
    uint32_t memType = 0xFFFFFFFF;
    for (uint32_t i = 0; i < mp.memoryTypeCount; i++)
        if ((mr.memoryTypeBits & (1u << i)) &&
            (mp.memoryTypes[i].propertyFlags & VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT) &&
            (mp.memoryTypes[i].propertyFlags & VK_MEMORY_PROPERTY_HOST_COHERENT_BIT)) { memType = i; break; }
    if (memType == 0xFFFFFFFF) { printf("  no host-visible coherent mem\n"); return -1; }
    VkMemoryAllocateInfo mai{}; mai.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
    mai.allocationSize = mr.size; mai.memoryTypeIndex = memType;
    VkDeviceMemory mem; CHECK(vkAllocateMemory(device, &mai, nullptr, &mem));
    CHECK(vkBindBufferMemory(device, buf, mem, 0));

    uint32_t* mapped = nullptr;
    CHECK(vkMapMemory(device, mem, 0, bytesz, 0, (void**)&mapped));
    for (uint32_t i = 0; i < N; i++) mapped[i] = i + 1;
    vkUnmapMemory(device, mem);

    VkDescriptorSetLayoutBinding bnd{}; bnd.binding = 0;
    bnd.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; bnd.descriptorCount = 1;
    bnd.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
    VkDescriptorSetLayoutCreateInfo dslci{}; dslci.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
    dslci.bindingCount = 1; dslci.pBindings = &bnd;
    VkDescriptorSetLayout dsl; CHECK(vkCreateDescriptorSetLayout(device, &dslci, nullptr, &dsl));
    VkPipelineLayoutCreateInfo plci{}; plci.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    plci.setLayoutCount = 1; plci.pSetLayouts = &dsl;
    VkPipelineLayout pll; CHECK(vkCreatePipelineLayout(device, &plci, nullptr, &pll));

    auto code = loadSpv(spvPath);
    VkShaderModuleCreateInfo smci{}; smci.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    smci.codeSize = code.size() * 4; smci.pCode = code.data();
    VkShaderModule sm; CHECK(vkCreateShaderModule(device, &smci, nullptr, &sm));

    VkPipelineShaderStageRequiredSubgroupSizeCreateInfoEXT reqSgInfo{};
    VkComputePipelineCreateInfo pci{}; pci.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    pci.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    pci.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT; pci.stage.module = sm; pci.stage.pName = "main";
    if (reqSg > 0) {
        reqSgInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_REQUIRED_SUBGROUP_SIZE_CREATE_INFO_EXT;
        reqSgInfo.requiredSubgroupSize = reqSg;
        pci.stage.pNext = &reqSgInfo;
    }
    pci.layout = pll;
    VkPipeline pipe; CHECK(vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &pci, nullptr, &pipe));

    VkDescriptorPoolSize dps{}; dps.type = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; dps.descriptorCount = 1;
    VkDescriptorPoolCreateInfo dpci{}; dpci.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
    dpci.maxSets = 1; dpci.poolSizeCount = 1; dpci.pPoolSizes = &dps;
    VkDescriptorPool dp; CHECK(vkCreateDescriptorPool(device, &dpci, nullptr, &dp));
    VkDescriptorSetAllocateInfo dsai{}; dsai.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;
    dsai.descriptorPool = dp; dsai.descriptorSetCount = 1; dsai.pSetLayouts = &dsl;
    VkDescriptorSet ds; CHECK(vkAllocateDescriptorSets(device, &dsai, &ds));
    VkDescriptorBufferInfo dbi{}; dbi.buffer = buf; dbi.offset = 0; dbi.range = bytesz;
    VkWriteDescriptorSet wds{}; wds.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
    wds.dstSet = ds; wds.dstBinding = 0; wds.descriptorCount = 1;
    wds.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; wds.pBufferInfo = &dbi;
    vkUpdateDescriptorSets(device, 1, &wds, 0, nullptr);

    VkCommandPool cpool; VkCommandPoolCreateInfo cpci{}; cpci.sType = VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO;
    cpci.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT; cpci.queueFamilyIndex = qfam;
    CHECK(vkCreateCommandPool(device, &cpci, nullptr, &cpool));
    VkCommandBuffer cb; VkCommandBufferAllocateInfo cbai{}; cbai.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO;
    cbai.commandPool = cpool; cbai.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY; cbai.commandBufferCount = 1;
    CHECK(vkAllocateCommandBuffers(device, &cbai, &cb));
    VkCommandBufferBeginInfo cbbi{}; cbbi.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
    CHECK(vkBeginCommandBuffer(cb, &cbbi));
    vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_COMPUTE, pipe);
    vkCmdBindDescriptorSets(cb, VK_PIPELINE_BIND_POINT_COMPUTE, pll, 0, 1, &ds, 0, nullptr);
    vkCmdDispatch(cb, N / 32, 1, 1);
    CHECK(vkEndCommandBuffer(cb));

    VkQueue q; vkGetDeviceQueue(device, qfam, 0, &q);
    VkSubmitInfo si{}; si.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO; si.commandBufferCount = 1; si.pCommandBuffers = &cb;
    CHECK(vkQueueSubmit(q, 1, &si, VK_NULL_HANDLE));
    CHECK(vkQueueWaitIdle(q));

    CHECK(vkMapMemory(device, mem, 0, bytesz, 0, (void**)&mapped));
    int fails = 0; uint32_t firstBadIdx = 0, firstBadGot = 0, firstBadExp = 0;
    for (uint32_t i = 0; i < N; i++) {
        uint32_t exp;
        if (kind == 0) exp = (i + 1) * 7u + 3u;
        else if (kind == 1) { uint32_t s = i / expSg; exp = s * expSg + 1u; }
        else { uint32_t s = i / expSg; exp = expSg * s * expSg + (expSg * (expSg + 1u)) / 2u; }
        if (mapped[i] != exp) { if (fails == 0) { firstBadIdx = i; firstBadGot = mapped[i]; firstBadExp = exp; } fails++; }
    }
    vkUnmapMemory(device, mem);

    const char* nm = (kind == 0) ? "no-subgroup(mul)" : (kind == 1) ? "subgroupBroadcast" : "subgroupAdd(reduce)";
    printf("  %-18s sg=%-3u %-7s (%d/%d wrong", nm, reqSg ? reqSg : expSg, fails == 0 ? "PASS" : "FAIL", fails, N);
    if (fails) printf("; first idx=%u got=%u exp=%u", firstBadIdx, firstBadGot, firstBadExp);
    printf(")\n");

    vkDestroyPipeline(device, pipe, nullptr); vkDestroyShaderModule(device, sm, nullptr);
    vkDestroyPipelineLayout(device, pll, nullptr); vkDestroyDescriptorSetLayout(device, dsl, nullptr);
    vkDestroyDescriptorPool(device, dp, nullptr); vkDestroyCommandPool(device, cpool, nullptr);
    vkDestroyBuffer(device, buf, nullptr); vkFreeMemory(device, mem, nullptr);
    return fails == 0 ? 0 : 1;
}

int main(int argc, char** argv) {
    const char* dir = (argc > 1) ? argv[1] : ".";
    if (volkInitialize() != VK_SUCCESS) { printf("volkInitialize failed\n"); return 2; }

    VkApplicationInfo ai{}; ai.sType = VK_STRUCTURE_TYPE_APPLICATION_INFO; ai.apiVersion = VK_API_VERSION_1_1;
    VkInstanceCreateInfo ici{}; ici.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO; ici.pApplicationInfo = &ai;
    VkInstance inst; CHECK(vkCreateInstance(&ici, nullptr, &inst));
    volkLoadInstance(inst);

    uint32_t nd = 0; vkEnumeratePhysicalDevices(inst, &nd, nullptr);
    std::vector<VkPhysicalDevice> pds(nd); vkEnumeratePhysicalDevices(inst, &nd, pds.data());
    VkPhysicalDevice phys = pds[0];
    VkPhysicalDeviceProperties props; vkGetPhysicalDeviceProperties(phys, &props);
    printf("Device: %s (api 0x%x)\n", props.deviceName, props.apiVersion);

    VkPhysicalDeviceSubgroupProperties sp{}; sp.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_PROPERTIES;
    VkPhysicalDeviceSubgroupSizeControlPropertiesEXT ssc{};
    ssc.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_SIZE_CONTROL_PROPERTIES_EXT;
    VkPhysicalDeviceProperties2 p2{}; p2.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2;
    p2.pNext = &sp; sp.pNext = &ssc;
    vkGetPhysicalDeviceProperties2(phys, &p2);
    printf("reported subgroupSize=%u  supportedOps=0x%x  stages=0x%x\n", sp.subgroupSize, sp.supportedOperations, sp.supportedStages);
    printf("subgroupSizeControl: min=%u max=%u maxFullSCWorkgroupSize=%u requiredStages=0x%x\n",
           ssc.minSubgroupSize, ssc.maxSubgroupSize, ssc.maxComputeWorkgroupSubgroups, ssc.requiredSubgroupSizeStages);

    VkPhysicalDeviceSubgroupSizeControlFeaturesEXT sscFeat{}; sscFeat.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_SIZE_CONTROL_FEATURES_EXT;
    VkPhysicalDeviceFeatures2 pdf2{}; pdf2.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FEATURES_2; pdf2.pNext = &sscFeat;
    vkGetPhysicalDeviceFeatures2(phys, &pdf2);
    printf("features: subgroupSizeControl=%d computeFullSubgroups=%d\n", sscFeat.subgroupSizeControl, sscFeat.computeFullSubgroups);

    uint32_t nqf = 0; vkGetPhysicalDeviceQueueFamilyProperties(phys, &nqf, nullptr);
    std::vector<VkQueueFamilyProperties> qfp(nqf); vkGetPhysicalDeviceQueueFamilyProperties(phys, &nqf, qfp.data());
    uint32_t qfam = 0; for (uint32_t i = 0; i < nqf; i++) if (qfp[i].queueFlags & VK_QUEUE_COMPUTE_BIT) { qfam = i; break; }

    float prio = 1.0f;
    VkDeviceQueueCreateInfo dqci{}; dqci.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
    dqci.queueFamilyIndex = qfam; dqci.queueCount = 1; dqci.pQueuePriorities = &prio;
    const char* exts[] = { VK_EXT_SUBGROUP_SIZE_CONTROL_EXTENSION_NAME };
    VkDeviceCreateInfo dci{}; dci.sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO;
    dci.queueCreateInfoCount = 1; dci.pQueueCreateInfos = &dqci;
    dci.enabledExtensionCount = (sscFeat.subgroupSizeControl ? 1u : 0u); dci.ppEnabledExtensionNames = exts;
    dci.pNext = (sscFeat.subgroupSizeControl ? &sscFeat : nullptr);
    VkDevice device; CHECK(vkCreateDevice(phys, &dci, nullptr, &device));
    volkLoadDevice(device);

    std::string sp_simple = std::string(dir) + "/simple.comp.spv";
    std::string sp_bc = std::string(dir) + "/broadcast.comp.spv";
    std::string sp_red = std::string(dir) + "/reduce.comp.spv";

    uint32_t repSg = sp.subgroupSize ? sp.subgroupSize : 32;
    printf("\n--- at DEFAULT subgroup size (%u) ---\n", repSg);
    int a = runTest(device, phys, qfam, sp_simple.c_str(), 0, repSg, 0);
    int b = runTest(device, phys, qfam, sp_bc.c_str(),    1, repSg, 0);
    int c = runTest(device, phys, qfam, sp_red.c_str(),   2, repSg, 0);

    int b16 = -1, c16 = -1;
    if (sscFeat.subgroupSizeControl && ssc.minSubgroupSize <= 16 && 16 <= ssc.maxSubgroupSize) {
        printf("\n--- at FORCED subgroup size 16 ---\n");
        b16 = runTest(device, phys, qfam, sp_bc.c_str(),  1, 16, 16);
        c16 = runTest(device, phys, qfam, sp_red.c_str(), 2, 16, 16);
    } else {
        printf("\n--- FORCED-16 not available (control=%d min=%u max=%u) ---\n",
               sscFeat.subgroupSizeControl, ssc.minSubgroupSize, ssc.maxSubgroupSize);
    }

    printf("\n=== VERDICT ===\n");
    printf("  no-subgroup(default):   %s\n", a==0?"OK":"BAD");
    printf("  subgroupBroadcast default=%s forced16=%s\n", b==0?"OK":"BAD", b16==0?"OK":(b16<0?"n/a":"BAD"));
    printf("  subgroupAdd      default=%s forced16=%s\n", c==0?"OK":"BAD", c16==0?"OK":(c16<0?"n/a":"BAD"));
    if (b16 == 0 && c16 == 0) printf("  ==> FORCING subgroup=16 FIXES subgroup ops => radix sort viable at 16-wide.\n");
    else if (b16 < 0)         printf("  ==> can't force 16 on this device => no workaround.\n");
