                     VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 0, NULL, 1, &bufferBarrier, 0,
                     NULL);

if (queryPool) {
  vkCmdWriteTimestamp(commandBuffer, VK_PIPELINE_STAGE_TRANSFER_BIT, queryPool, query + 1);
}

PushConstants pushConstants;
pushConstants.maxElementCount = elementCount;
for (int pass = 0; pass < 4; ++pass) {
  pushConstants.pass = pass;

  int writeCount = 5;
  VkDescriptorBufferInfo buffers[7];
  buffers[0] = {storageBuffer, elementCountOffset, sizeof(elementCount)};
  buffers[1] = {storageBuffer, histogramOffset, sizeof(uint32_t) * 4 * RADIX};
  buffers[2] = {storageBuffer, histogramOffset + sizeof(uint32_t) * 4 * RADIX,
                VK_WHOLE_SIZE};  // TODO: get exact buffer size
  buffers[3] = {keysBuffer, keysOffset, inoutSize};
  buffers[4] = {storageBuffer, inoutOffset, inoutSize};
  if (valuesBuffer) {
    writeCount = 7;
    buffers[5] = {valuesBuffer, valuesOffset, inoutSize};
    buffers[6] = {storageBuffer, inoutOffset + Align(inoutSize, align), inoutSize};
  }

  // switch in->out to out->in for pass 1, pass 3
  if (pass % 2 == 1) {
    VkDescriptorBufferInfo tmp = buffers[3];
    buffers[3] = buffers[4];
    buffers[4] = tmp;
    if (valuesBuffer) {
      tmp = buffers[5];
      buffers[5] = buffers[6];
      buffers[6] = tmp;
    }
  }

  VkWriteDescriptorSet writes[7];
  for (int i = 0; i < writeCount; ++i) {
    writes[i] = {VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
    writes[i].dstSet =
        sorter->usePushDescriptors ? VK_NULL_HANDLE : sorter->descriptorSets[pass];
    writes[i].dstBinding = i;
    writes[i].descriptorCount = 1;
    writes[i].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;
    writes[i].pBufferInfo = &buffers[i];
  }

  if (sorter->usePushDescriptors) {
    sorter->cmdPushDescriptorSet(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, pipelineLayout, 0,
                                 writeCount, writes);
  } else {
    vkUpdateDescriptorSets(device, writeCount, writes, 0, NULL);
    vkCmdBindDescriptorSets(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, pipelineLayout, 0, 1,
                            &sorter->descriptorSets[pass], 0, NULL);
  }

