117	SortData makeStressData(uint32_t n, uint32_t pattern, uint32_t seed) {
118	  SortData data;
119	  data.keys.resize(n);
120	  data.values.resize(n);
121	  std::mt19937 rng(seed);
122	
123	  for (uint32_t i = 0; i < n; ++i) {
124	    data.values[i] = i;
125	    switch (pattern) {
126	      case 0: data.keys[i] = 0; break;
127	      case 1: data.keys[i] = std::numeric_limits<uint32_t>::max(); break;
128	      case 2: data.keys[i] = i; break;
129	      case 3: data.keys[i] = n - i; break;
130	      case 4:
131	        data.keys[i] = (i & 1) ? std::numeric_limits<uint32_t>::max() : 0;
132	        break;
133	      case 5: data.keys[i] = i & 3; break;
134	      case 6: data.keys[i] = (i * 2654435761u) & 0xffu; break;
135	      default: data.keys[i] = rng(); break;
136	    }
137	  }
138	  return data;
139	}
